struct Der {const BYTE* data;UINT bytes,at=0;bool Next(BYTE& tag,Der& value){if(at+2>bytes)return false;tag=data[at++];UINT size=data[at++];if(size&128){UINT count=size&127;if(!count||count>4||at+count>bytes||!data[at])return false;size=0;for(UINT i=0;i<count;++i)size=(size<<8)|data[at++];if(size<128)return false;}if(size>bytes-at)return false;value={data+at,size,0};at+=size;return true;}};
