bool Oid(Der value,char* out){if(!value.bytes)return false;UINT at=0;auto number=[&](uint64_t n){char digits[24];UINT count=0;do{digits[count++]=char('0'+n%10);n/=10;}while(n);if(at+count>=96)return false;while(count)out[at++]=digits[--count];out[at]=0;return true;};uint64_t n=0;bool first=true;for(UINT i=0;i<value.bytes;++i){if(n>(UINT64_MAX>>7))return false;n=(n<<7)|(value.data[i]&127);if(!(value.data[i]&128)){if(first){const UINT a=n<40?0:n<80?1:2;if(!number(a))return false;out[at++]='.';n-=a*40;first=false;}else out[at++]='.';if(at>=95||!number(n))return false;n=0;}else if(i+1==value.bytes)return false;}return !first;}
