bool Matching(Cert* a,Cert* b){return a&&b&&a->info.SerialNumber.cbData==b->info.SerialNumber.cbData&&a->info.Issuer.cbData==b->info.Issuer.cbData&&Equal(a->info.SerialNumber.pbData,b->info.SerialNumber.pbData,a->info.SerialNumber.cbData)&&Equal(a->info.Issuer.pbData,b->info.Issuer.pbData,a->info.Issuer.cbData);}
Cert* Decode(const BYTE* data,UINT bytes){if(!data||!bytes||bytes>8192)return nullptr;Cert** slot=nullptr;for(auto& c:certificates)if(!c){slot=&c;break;}if(!slot)return nullptr;auto* c=Make<Cert>();if(!c)return nullptr;c->encoded=static_cast<BYTE*>(Allocate(bytes));if(!c->encoded){Destroy(c);return nullptr;}Copy(c->encoded,data,bytes);br_x509_decoder_init(&c->decoder,Distinguished,c);br_x509_decoder_push(&c->decoder,data,bytes);if(br_x509_decoder_last_error(&c->decoder)||!br_x509_decoder_get_pkey(&c->decoder)||c->overflow){Release(c->encoded);Destroy(c);return nullptr;}c->context.dwCertEncodingType=X509_ASN_ENCODING;c->context.pbCertEncoded=c->encoded;c->context.cbCertEncoded=bytes;c->context.pCertInfo=&c->info;if(!Metadata(*c)){Release(c->encoded);Destroy(c);return nullptr;}*slot=c;return c;}
void LoadRoot(){if(loadedRoot)return;loadedRoot=true;HKEY key=nullptr;BYTE der[512]{};DWORD bytes=sizeof(der),type=0;if(RegOpenKeyExW(HKEY_CURRENT_USER,L"Software\\Guardian\\Trust",0,KEY_READ,&key)==ERROR_SUCCESS){if(RegQueryValueExW(key,L"Root",nullptr,&type,der,&bytes)==ERROR_SUCCESS&&type==REG_BINARY){auto* root=Decode(der,bytes);if(root&&br_x509_decoder_isCA(&root->decoder))rootCertificate=root;else ReleaseCert(root);}RegCloseKey(key);}}
