bool ServerUsage(const BYTE* data,UINT bytes){Der document{data,bytes},certificate{},tbs{},field{};BYTE tag=0;if(!document.Next(tag,certificate)||tag!=0x30||document.at!=bytes||!certificate.Next(tag,tbs)||tag!=0x30)return false;if(tbs.at<tbs.bytes&&tbs.data[tbs.at]==0xA0&&!tbs.Next(tag,field))return false;for(UINT i=0;i<6;++i)if(!tbs.Next(tag,field))return false;while(tbs.at<tbs.bytes){if(!tbs.Next(tag,field))return false;if(tag!=0xA3)continue;Der extensions{};if(!field.Next(tag,extensions)||tag!=0x30)return false;while(extensions.at<extensions.bytes){Der extension{},oid{},payload{};if(!extensions.Next(tag,extension)||tag!=0x30||!extension.Next(tag,oid)||tag!=6)return false;const bool eku=oid.bytes==3&&oid.data[0]==0x55&&oid.data[1]==0x1D&&oid.data[2]==0x25;if(!extension.Next(tag,payload))return false;if(tag==1&&!extension.Next(tag,payload))return false;if(tag!=4)return false;if(eku){Der usages{};if(!payload.Next(tag,usages)||tag!=0x30)return false;bool server=false;constexpr BYTE serverOid[]{0x2B,6,1,5,5,7,3,1};while(usages.at<usages.bytes){Der usage{};if(!usages.Next(tag,usage)||tag!=6)return false;if(usage.bytes==sizeof(serverOid)&&Equal(usage.data,serverOid,sizeof(serverOid)))server=true;}if(!server)return false;}}}return true;}
